# owner: platform
import unittest

from hourglass.rounding import round_labels, round_span
from hourglass.parsing import parse_span
from hourglass.models import Span

class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90, 2.5, True):
            with self.assertRaises(ValueError, msg=repr(step)):
                round_labels([Span(540, 600)], step)

    def test_bad_step_raises_for_no_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_good_steps_accepted(self):
        for step in (1, 5, 15, 30, 60):
            self.assertEqual(len(round_labels([Span(0, 1440)], step)), 1)

class RoundSpanTests(unittest.TestCase):
    def test_nearest_step(self):
        self.assertEqual(round_span(parse_span("09:07-17:08"), 15), parse_span("09:00-17:15"))

    def test_halfway_goes_up(self):
        self.assertEqual(round_span(Span(545, 600), 10), Span(550, 600))
        self.assertEqual(round_span(Span(60, 65), 10), Span(60, 70))

    def test_end_of_day_stays(self):
        self.assertEqual(round_span(Span(1400, 1440), 30), Span(1410, 1440))

    def test_span_collapsing_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 545), 15)

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:02-17:14"), parse_span("18:00-18:30")]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)", "18:00-18:30 (0h 30m)"]
        )

    def test_empty(self):
        self.assertEqual(round_labels([], 15), [])
